def lint(dockerfile):
    warnings = []
    copied_all = False
    for n, raw in enumerate(dockerfile.splitlines(), 1):
        parts = raw.strip().split()
        if not parts:
            continue
        kw = parts[0].upper()
        if kw == 'FROM' and len(parts) > 1:
            image = parts[1]
            if image.lower() != 'scratch' and '@sha256:' not in image:
                name_tag = image.rsplit('/', 1)[-1]
                tag = name_tag.split(':', 1)[1] if ':' in name_tag else None
                if tag is None or tag == 'latest':
                    warnings.append(f'L{n}: unpinned image')
        elif kw == 'COPY' and parts[1:] == ['.', '.']:
            copied_all = True
        elif kw == 'RUN' and copied_all and parts[1:3] in (['npm', 'ci'], ['npm', 'install']):
            warnings.append(f'L{n}: copy before install')
    return warnings

