async function waitForServices(check, names, { timeout = 1000, interval = 20 } = {}) {
  const deadline = Date.now() + timeout;
  let rounds = 0;
  for (;;) {
    rounds++;
    const states = await Promise.all(names.map(async n => [n, await check(n)]));
    const bad = states.find(([, s]) => s === 'unhealthy');
    if (bad) throw new Error(`${bad[0]} is unhealthy`);
    const waiting = states.filter(([, s]) => s !== 'healthy').map(([n]) => n);
    if (waiting.length === 0) return rounds;
    if (Date.now() >= deadline) throw new Error('timed out waiting for: ' + waiting.join(', '));
    await new Promise(r => setTimeout(r, interval));
  }
}
